"""The method check steps (TRAIN-06, AD-09): PL-01 steps 2, 3, 6 and PL-03 step 5."""

from collections.abc import Mapping, Sequence

import numpy as np

from rllab.core.types import Array, Box, WorldSpec
from rllab.methods import make_learner
from rllab.methods.types import Learner, MethodConfig, Transition
from rllab.train.types import CheckFailedError, CheckResult, RunConfig
from rllab.worlds.checks import CheckDiscrete
from rllab.worlds.types import CheckWorld

CHECK_BUDGET = 5_000
"""World steps each method trains on its check world."""

PASS_AGREEMENT = 0.95
BOX_TOLERANCE = 0.1
SCORE_SEED = 0


def check_world(method: str) -> CheckWorld:
    """The check world of `method` (AD-09); M1 has DQN's corridor only."""
    if method == "dqn":
        return CheckDiscrete()
    raise ValueError(f"no check world for method {method!r}")


def check_plan(configs: Sequence[RunConfig]) -> dict[str, MethodConfig]:
    """Each distinct team method, keyed by method name, with `check_settings` applied."""
    plan: dict[str, MethodConfig] = {}
    for config in configs:
        for team_method in config.methods.values():
            if team_method.method in plan:
                continue
            overrides = config.check_settings.get(team_method.method, {})
            settings = {**team_method.settings, **overrides}
            plan[team_method.method] = MethodConfig(team_method.method, settings)
    return plan


def train_checks(plan: Mapping[str, MethodConfig], seed: int) -> dict[str, Learner]:
    """A learner per method, trained on its check world for the fixed check budget."""
    learners: dict[str, Learner] = {}
    for method, config in plan.items():
        world = check_world(method)
        learner_seq, play_seq = np.random.SeedSequence(seed).spawn(2)
        team = world.spec.teams[0].name
        learner = make_learner(config, world.spec, team, np.random.default_rng(learner_seq))
        _train(world, learner, np.random.default_rng(play_seq))
        learners[method] = learner
    return learners


def _train(world: CheckWorld, learner: Learner, rng: np.random.Generator) -> None:
    """Step `world` with `learner` for `CHECK_BUDGET` world steps, resetting after each end."""
    rows = list(world.spec.teams[0].agents)
    step = world.reset(int(rng.integers(2**31)))
    for _ in range(CHECK_BUDGET):
        actions = learner.act(step.obs[rows], rng)
        after = world.step(actions)
        learner.observe(
            Transition(
                obs=step.obs[rows],
                actions=actions,
                rewards=after.rewards[rows],
                next_obs=after.obs[rows],
                done=after.done,
                truncated=after.truncated,
                active=after.active[rows],
            )
        )
        step = world.reset(int(rng.integers(2**31))) if after.done else after


def score_checks(
    learners: Mapping[str, Learner], plan: Mapping[str, MethodConfig]
) -> list[CheckResult]:
    """Per method, the share of check-world states where `policy().act` is the best action."""
    results = []
    for method in plan:
        world = check_world(method)
        rng = np.random.default_rng(np.random.SeedSequence(SCORE_SEED))
        actions = learners[method].policy().act(world.states(), rng)
        agreement = _agreement(actions, world.best_actions(), world.spec)
        results.append(
            CheckResult(method, world.spec.world, agreement, agreement >= PASS_AGREEMENT)
        )
    return results


def _agreement(actions: Array, best: Array, spec: WorldSpec) -> float:
    """Share of rows of `actions` equal to `best` (within `BOX_TOLERANCE` per dimension)."""
    if isinstance(spec.action, Box):
        hits = np.all(np.abs(actions - best) <= BOX_TOLERANCE, axis=-1)
    else:
        hits = np.asarray(actions) == best
    return float(np.mean(hits))


def require_pass(results: Sequence[CheckResult]) -> list[CheckResult]:
    """`results` unchanged if all passed; `CheckFailedError` on the first failure."""
    failed = next((r for r in results if not r.passed), None)
    if failed is not None:
        raise CheckFailedError(failed)
    return list(results)

